css:
a { text-decoration: none; }
p { margin: 0; }
h1, h2, h3 { margin: 0; padding: 0; }
.nl-hl { -webkit-box-decoration-break: clone; box-decoration-break: clone; }
.nl-strike { text-decoration: line-through; }
@media only screen and (max-width: 580px) {
  .nl-hero-h1-m { font-size: 20px !important; line-height: 28px !important; }
  .nl-hero-h1-l { font-size: 26px !important; line-height: 32px !important; }
  .nl-hero-h1-xl { font-size: 33px !important; line-height: 40px !important; }
  .nl-hero-text { padding-bottom: 90px !important; }
  .nl-hero-text.nl-hero-tall { padding-bottom: 220px !important; }
  .nl-card-media > table > tbody > tr > td,
  .nl-card-media > div > table > tbody > tr > td { padding-top: 170px !important; }
  .nl-card-heading div { font-size: 21px !important; line-height: 29px !important; }
  .nl-section-heading div { font-size: 22px !important; line-height: 30px !important; }
  .nl-header-link div { font-size: 13px !important; }
  .nl-hide-mobile { display: none !important; }
}
